import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a tight-fit bonus: leftover space is penalised linearly,
    and placements that leave almost no gap (relative to capacity) get an extra
    exponential bonus, so near-perfect fits are preferred over merely tight ones."""
    cap = float(np.max(bins))
    if cap <= 0.0:
        return np.zeros_like(bins, dtype=float)
    r = (bins - item) / cap                 # normalised leftover after placing item
    score = -r + 0.3 * np.exp(-r / 0.05)    # tight-fit bonus decays with leftover
    return np.asarray(score, dtype=float)

